#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const long long INF = -1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> w(n + 1, vector<int>(n + 1));
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            cin >> w[i][j];

    vector<vector<long long>> f(n + 1, vector<long long>(n + 1, INF));
    f[1][1] = w[1][1];

    // 四种跳跃的 (行变化, 列变化)
    int dx[4] = {2, -2, 1, -1};
    int dy[4] = {1, 1, 2, 2};

    for (int j = 2; j <= n; ++j) {          // 按列更新
        for (int i = 1; i <= n; ++i) {      // 遍历所有行
            for (int k = 0; k < 4; ++k) {
                int pi = i - dx[k];
                int pj = j - dy[k];
                if (pi >= 1 && pi <= n && pj >= 1 && pj <= n) {
                    if (f[pi][pj] != INF) {
                        f[i][j] = max(f[i][j], f[pi][pj] + w[i][j]);
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (f[i][j] > ans)
                ans = f[i][j];

    cout << ans << '\n';
    return 0;
}
